create or replace function public.secure_ui_metric_summary(p_branch_id bigint,p_from date,p_to date,p_doctor_id bigint default null,p_service_ids bigint[] default null) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare a_count bigint;c_count bigint;i_count bigint;v_total numeric;v_paid numeric;v_remaining numeric;
begin if p_branch_id is null or p_branch_id<>public.current_branch_id() then raise exception 'Forbidden';end if;
select count(*),count(distinct customer_id) filter(where status='completed') into a_count,c_count from appointments a where a.clinic_id=public.current_clinic_id() and a.branch_id=p_branch_id and a.appointment_at>=p_from::timestamp and a.appointment_at<p_to::timestamp+interval '1 day' and(p_doctor_id is null or a.doctor_id=p_doctor_id) and(p_service_ids is null or a.service_id=any(p_service_ids));
select count(*),coalesce(sum(p.amount),0),coalesce(sum(coalesce(p.paid_amount,case when p.payment_status='paid' then p.amount else 0 end)),0),coalesce(sum(coalesce(p.balance_due,0)),0) into i_count,v_total,v_paid,v_remaining from payments p left join appointments a on a.id=p.appointment_id where p.clinic_id=public.current_clinic_id() and p.branch_id=p_branch_id and coalesce(p.payment_date,p.created_at)>=p_from::timestamp and coalesce(p.payment_date,p.created_at)<p_to::timestamp+interval '1 day' and(p_doctor_id is null or a.doctor_id=p_doctor_id) and(p_service_ids is null or a.service_id=any(p_service_ids) or p.service_id=any(p_service_ids));
return jsonb_build_object('appointments',case when public.has_hr_permission('dashboard.appointments_count.view') then a_count else null end,'completedPatients',case when public.has_hr_permission('dashboard.completed_patients_count.view') then c_count else null end,'invoiceCount',case when public.has_hr_permission('dashboard.invoice_count.view') or public.has_hr_permission('payments.invoice_count.view') then i_count else null end,'collected',case when public.has_hr_permission('dashboard.collections_total.view') then v_paid else null end,'invoiced',case when public.has_hr_permission('dashboard.invoiced_total.view') or public.has_hr_permission('payments.total.view') then v_total else null end,'paid',case when public.has_hr_permission('dashboard.paid_total.view') or public.has_hr_permission('payments.paid_total.view') then v_paid else null end,'remaining',case when public.has_hr_permission('dashboard.remaining_total.view') or public.has_hr_permission('payments.remaining_total.view') then v_remaining else null end);end$$;
grant execute on function public.secure_ui_metric_summary(bigint,date,date,bigint,bigint[]) to authenticated;
